import {expect as baseExpect} from '@playwright/test'
import {randomUUID,randomBytes} from 'node:crypto'
import {expectSuccess,expectDatabaseError} from '../../scripts/staging/assertions.mjs'
const expect=baseExpect.configure({timeout:30000})
export async function siteWorkflow({browser,origin,actors,options={},capture=async()=>{},record=()=>{}}){
 const company=randomUUID(),other=randomUUID(),tag='SYNTHETIC returning site '+company.slice(0,6),contexts=[]
 const rpc=(role,fn,command,p={})=>actors[role].client.rpc(fn,{command,p:{companyId:company,requestId:randomUUID(),...p}})
 const cmd=(role,n,p={})=>rpc(role,'ts_command',n,p).then(expectSuccess),siteCmd=(role,n,p={})=>rpc(role,'ts_site_command',n,p).then(expectSuccess)
 const rows=(role,table,id,key='id')=>actors[role].client.from(table).select('*').eq(key,id).then(expectSuccess)
 async function login(role){const {localOnly,...settings}=options,context=await browser.newContext({viewport:{width:390,height:844},...settings});contexts.push(context);if(localOnly)await context.route('**/*',r=>[origin,actors[role].apiOrigin].includes(new URL(r.request().url()).origin)?r.continue():r.abort());const page=await context.newPage();page.setDefaultTimeout(30000);page.setDefaultNavigationTimeout(90000);await page.goto(origin+'/auth/login');await page.getByLabel('Email',{exact:true}).fill(actors[role].email);await page.getByLabel('Password',{exact:true}).fill(actors[role].password);await page.getByRole('button',{name:'Sign In',exact:true}).click();await page.waitForURL('**/dashboard');return page}
 const saved=page=>expect(page.locator('.save-state')).toHaveText('Saved')
 try{
  await cmd('OWNER','create_company',{id:company,name:tag});await cmd('SUPERVISOR','create_company',{id:other,name:tag+' other company'})
  const token=randomBytes(32).toString('hex');await cmd('OWNER','invite',{email:actors.WORKER.email,role:'worker',token});await cmd('WORKER','accept_invitation',{token})
  const otherSite=await siteCmd('SUPERVISOR','create',{companyId:other,id:randomUUID(),document:{name:tag,address:'SYNTHETIC other company',instructions:''}})
  const page=await login('WORKER'),ctx=page.context(),owner=await login('OWNER'),api=origin+'/api/sites'
  await page.goto(origin+'/dashboard?company='+company);await page.getByRole('link',{name:'Sites',exact:true}).click();await expect(page.getByText('0 matching sites',{exact:true})).toBeVisible()
  await page.getByRole('link',{name:'New site',exact:true}).click();await page.getByLabel('Site name',{exact:true}).fill(tag);await page.getByLabel('Address or location description',{exact:true}).fill('SYNTHETIC west loading entrance');await page.getByLabel('Site instructions (optional)',{exact:true}).fill('SYNTHETIC report to gate contact')
  // Simulate a response loss after the real server commits creation.
  let lost=false
  await ctx.route(api,async route=>{if(route.request().postDataJSON()?.command==='create'&&!lost){lost=true;const r=await route.fetch();expect(r.status()).toBe(200);await route.abort()}else await route.continue()})
  await page.getByRole('button',{name:'Create site',exact:true}).click();await expect(page.getByRole('button',{name:'Retry site operation',exact:true})).toBeVisible()
  await page.getByRole('button',{name:'Retry site operation',exact:true}).click();await page.waitForURL(/\/sites\/[a-f0-9-]{36}$/);await ctx.unroute(api)
  const id=new URL(page.url()).pathname.split('/').at(-1),readSite=async()=>(await rows('OWNER','ts_sites',id))[0]
  expect((await actors.WORKER.client.from('ts_sites').select('*').eq('company_id',company).then(expectSuccess))).toHaveLength(1)
  await page.reload();await expect(page.getByRole('heading',{name:tag,exact:true})).toBeVisible();await capture(page,'site-empty')
  await page.getByRole('button',{name:'Start today’s brief',exact:true}).click();await page.waitForURL(/\/briefs\/[a-f0-9-]{36}$/)
  const briefId=new URL(page.url()).pathname.split('/').at(-1)
  await expect(page.getByLabel('Site name or address',{exact:true})).toHaveValue(tag+' — SYNTHETIC west loading entrance')
  await page.getByLabel('Work date',{exact:true}).fill('2026-09-22');await page.getByLabel('Jurisdiction',{exact:true}).selectOption('CA-ON');await page.getByLabel('Workplace context',{exact:true}).selectOption('construction');await page.getByLabel('I have checked the jurisdiction and workplace context for this record.',{exact:true}).check();await saved(page)
  await page.getByRole('button',{name:'Continue',exact:true}).click();await page.getByLabel('Today’s work',{exact:true}).fill('SYNTHETIC bring materials to bay');await page.getByLabel('Responsible site contact',{exact:true}).fill('SYNTHETIC contact at entrance');await page.getByRole('checkbox',{name:actors.WORKER.email,exact:true}).check();await saved(page)
  await page.getByRole('button',{name:'Continue',exact:true}).click();await page.getByRole('button',{name:'Add task step and hazard',exact:true}).click();await page.getByLabel('Task step',{exact:true}).fill('SYNTHETIC material move');await page.getByLabel('Hazard or concern',{exact:true}).fill('SYNTHETIC obstructed route');await page.getByLabel('Control or precaution',{exact:true}).fill('SYNTHETIC proposed route clearance');await page.getByLabel('Responsible for this control',{exact:true}).selectOption(actors.WORKER.id);await saved(page)
  await page.getByRole('button',{name:'Continue',exact:true}).click();await page.getByLabel('What was discussed in the briefing?',{exact:true}).fill('SYNTHETIC route and unresolved concern');await saved(page);await page.getByRole('button',{name:'Record briefing version',exact:true}).click();await page.getByRole('button',{name:'Acknowledge this version',exact:true}).click();await expect(page.getByRole('status')).toContainText('Your acknowledgement is recorded')
  const versions=await rows('OWNER','ts_brief_versions',briefId,'brief_id'),original=versions[0],acks=await rows('OWNER','ts_brief_acknowledgements',briefId,'brief_id')
  expect(original.snapshot.site.name).toBe(tag);expect(acks).toHaveLength(1)
  const exportHref=await page.getByRole('link',{name:'Export daily brief',exact:true}).getAttribute('href'),exportBefore=await ctx.request.get(origin+exportHref);expect(exportBefore.status()).toBe(200);const html=await exportBefore.text();expect(html).toContain('SYNTHETIC report to gate contact')
  await page.getByRole('link',{name:'Back to site: '+tag,exact:true}).click();await expect(page.getByText('1 needing attention · 0 awaiting verification · 0 completed',{exact:true})).toBeVisible()
  await page.getByText('Reuse a previous task description',{exact:true}).click();await page.getByLabel('Starting task (optional)',{exact:true}).selectOption(briefId);await page.getByRole('button',{name:'Start today’s brief',exact:true}).click();await page.waitForURL(/\/briefs\/[a-f0-9-]{36}$/)
  const nextId=new URL(page.url()).pathname.split('/').at(-1),next=(await rows('OWNER','ts_briefs',nextId))[0]
  expect(next.document.task).toBe('SYNTHETIC bring materials to bay');for(const k of ['crew','steps','attendance'])expect(next.document[k]).toEqual([]);expect(next.document.confirmed).toBe(false);expect(next.document.date).toBe('')
  await page.getByRole('link',{name:'Back to site: '+tag,exact:true}).click();await page.getByRole('link',{name:/Date not set · Resume brief/}).click();expect(new URL(page.url()).pathname).toBe('/briefs/'+nextId)
  await page.getByRole('link',{name:'Back to site: '+tag,exact:true}).click();await page.getByRole('link',{name:'New site report',exact:true}).click();await page.getByRole('button',{name:'Create saved draft',exact:true}).click();await page.waitForURL(/\/report\/[a-f0-9-]{36}/)
  const reportId=new URL(page.url()).pathname.split('/').at(-1),reportDraft=(await rows('OWNER','ts_reports',reportId))[0];expect(reportDraft.document.job.address).toBe('SYNTHETIC west loading entrance');expect(reportDraft.site_snapshot.name).toBe(tag)
  await page.getByRole('link',{name:'Back to site: '+tag,exact:true}).click();await page.getByRole('link',{name:'View site reports',exact:true}).click();await page.getByLabel('Report status',{exact:true}).selectOption('draft');await page.getByRole('button',{name:'Find reports',exact:true}).click();await expect(page.getByRole('status')).toContainText('1 matching report')
  await page.getByRole('link',{name:/SYNTHETIC west loading entrance/}).click();await page.getByRole('link',{name:'Back to reports',exact:true}).click();expect(new URL(page.url()).searchParams.get('site')).toBe(id);expect(new URL(page.url()).searchParams.get('status')).toBe('draft')
  await page.goto(origin+'/sites/'+id);await page.getByRole('link',{name:'Site actions (1 outstanding)',exact:true}).click();await expect(page.getByText('SYNTHETIC obstructed route',{exact:true}).first()).toBeVisible();await page.getByLabel('Work status',{exact:true}).selectOption('attention');await page.getByRole('button',{name:'Show actions',exact:true}).click()
  const action=(await rows('OWNER','ts_actions',briefId,'brief_id'))[0];await page.locator('#action-'+action.id+' summary').first().click();await page.getByRole('link',{name:'Open original hazard and control',exact:true}).click();await page.getByRole('link',{name:'Back to actions',exact:true}).click();expect(new URL(page.url()).searchParams.get('site')).toBe(id);expect(new URL(page.url()).searchParams.get('focus')).toBe(action.id)
  await capture(page,'site-actions')
  await page.goto(origin+'/sites/'+id);await page.getByText('Manage site',{exact:true}).click();await page.getByLabel('Site name',{exact:true}).fill(tag+' renamed')
  await ctx.route(api,r=>r.request().postDataJSON()?.command==='save'?r.abort():r.continue());await page.getByRole('button',{name:'Save site details',exact:true}).click();await expect(page.getByRole('button',{name:'Retry site operation',exact:true})).toBeVisible();await expect(page.getByLabel('Site name',{exact:true})).toHaveValue(tag+' renamed');expect((await readSite()).document.name).toBe(tag)
  await ctx.unroute(api);await page.getByRole('button',{name:'Retry site operation',exact:true}).click();await expect(page.getByRole('heading',{name:tag+' renamed',exact:true})).toBeVisible();await page.reload();await expect(page.getByRole('heading',{name:tag+' renamed',exact:true})).toBeVisible()
  expect((await ctx.request.get(origin+exportHref)).status()).toBe(200);expect((await rows('OWNER','ts_brief_versions',briefId,'brief_id'))[0]).toEqual(original);expect(await rows('OWNER','ts_brief_acknowledgements',briefId,'brief_id')).toEqual(acks);expect((await rows('OWNER','ts_reports',reportId))[0]).toEqual(reportDraft)
  expectDatabaseError(await rpc('WORKER','ts_site_command','link_report',{id:reportId,siteId:otherSite}),'TS_not_found')
  expectDatabaseError(await rpc('WORKER','ts_site_command','save',{id,revision:1,document:{name:'stale',address:'stale',instructions:''}}),'TS_conflict')
  expectDatabaseError(await rpc('WORKER','ts_site_command','archive',{id,revision:(await readSite()).revision}),'TS_denied')
  await owner.goto(origin+'/sites/'+id);await owner.getByText('Manage site',{exact:true}).click();await owner.getByText('Archive site',{exact:true}).click();await owner.getByRole('button',{name:'Confirm archive',exact:true}).click();await expect(owner.getByText('Archived site',{exact:true})).toBeVisible();await page.reload();await expect(page.getByRole('button',{name:'Start today’s brief',exact:true})).toHaveCount(0);await expect(page.getByRole('link',{name:'New site report',exact:true})).toHaveCount(0)
  expectDatabaseError(await rpc('WORKER','ts_site_command','create_brief',{id:randomUUID(),siteId:id}),'TS_site_archived');await capture(page,'site-archived')
  await cmd('OWNER','member',{userId:actors.WORKER.id,role:'remove'});expect(await rows('WORKER','ts_sites',id)).toHaveLength(0);expect(await rows('WORKER','ts_site_links',id,'site_id')).toHaveLength(0);expect(await rows('WORKER','ts_site_actions',id,'site_id')).toHaveLength(0)
  const denial=await ctx.request.post(api,{headers:{origin,'x-expected-actor':actors.WORKER.id},data:{command:'save',payload:{companyId:company,id,revision:3,requestId:randomUUID(),document:{name:'denied',address:'denied',instructions:''}}}});expect(denial.status()).toBe(403)
  record('Site create/reload, lost-response retry, brief/report resume, fresh-day reuse, scoped action counts/navigation, interrupted save, archive/roles/revocation and unchanged historical snapshots PASS',{company,siteId:id,briefId,reportId})
 }finally{for(const c of contexts)await c.close()}
}
